(6423629, 952949, 58634, '<td valign="top">That blends in quite well! Great capture.</td>', 'That blends in quite well! Great capture.', '2011-05-24 20:06:33.000000', NULL, 1),
(6423630, 952886, 58634, '<td valign="top">The dogs facial expression is so classy. Like an old school portrait almost. It''s comical. Very cute. My only critique is the little bit of paw that you cut off to the right.</td>', 'The dogs facial expression is so classy. Like an old school portrait almost. It''s comical. Very cute. My only critique is the little bit of paw that you cut off to the right.', '2011-05-24 20:15:38.000000', NULL, 1),
